authHttp.request("/api/secure/profile", "GET");
```

### 方案 C：API 分层封装（类型安全）

> 给每个后端接口包一层函数：在函数里固定 `auth:true/false`，业务层不再关心 `auth`。

```ts
// 复杂逻辑：在 API 层固定鉴权语义
export const Api = {
  getFeedNews: () =>
    http.request<Feed[]>("/api/pub/get_feednews", "GET", undefined, {
      auth: false,
    }),
  getProfile: () => http.request<Profile>("/api/secure/profile", "GET"), // 默认为鉴权
};
```

