  if (auth.isAuthenticated && to.name === LOGIN_ROUTE.name) {
    // 已登录访问登录页 → 重定向
  }

  if (!auth.isAuthenticated && !publicRoute) {
    // 未登录访问受保护页 → 去登录
  }

  return next();
