```typescript
export const useAuthStore = defineStore(
  "auth",
  () => {
    // ...
    return {
      /* ... */
    };
  },
  {
    persist: {
      afterHydrate: (ctx) => {
        // ✨ 利用插件生命周期
        if (!ctx.store.ready) {
          ctx.store.ready = true;
          _resolveReadyList.splice(0).forEach((r) => r());
        }
      },
    },
  }
);
