# Riverpod 最佳实践：WidgetsBinding + Provider Family 完整指南

> 本文综合讲解如何在实际项目中正确使用 Riverpod，结合 WidgetsBinding 实现优雅的状态初始化。

## 经典场景：首帧后初始化

### 问题描述

```dart
// ❌ 常见错误写法
class MyPage extends ConsumerStatefulWidget {
  @override
  ConsumerState<MyPage> createState() => _MyPageState();
}

class _MyPageState extends ConsumerState<MyPage> {
  @override
  void initState() {
    super.initState();
    // 错误1：可能还没有布局信息
    ref.read(provider).init();

    // 错误2：在 initState 中调用 setState
    setState(() {});

    // 错误3：在 initState 中显示对话框
    showDialog(...); // 报错！
  }

  @override
  Widget build(BuildContext context) {
    return Container();
  }
}
```

### 正确解决方案

```dart
class MyPage extends ConsumerStatefulWidget {
  const MyPage({super.key, required this.id});
  final String id;

  @override
  ConsumerState<MyPage> createState() => _MyPageState();
}

class _MyPageState extends ConsumerState<MyPage> {
  @override
  void initState() {
    super.initState();

    // ✅ 正确：使用 addPostFrameCallback
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return; // 必须检查

      ref.read(myProvider(widget.id).notifier).init();
    });
  }

  @override
  Widget build(BuildContext context) {
    final state = ref.watch(myProvider(widget.id));

    return Scaffold(
      body: state.loading
          ? const CircularProgressIndicator()
          : Text(state.data),
    );
  }
}
```

## 完整实战示例

### 场景：商品编辑页面

这是一个真实项目中的典型场景：根据商品ID加载数据并编辑。

#### 1. 定义状态和控制器

```dart
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

// ===== 状态定义 ===== //

@immutable
class ProductState {
  const ProductState({
    this.inited = false,
    this.loading = false,
    this.error,
    this.name = '',
    this.price = 0.0,
    this.description = '',
  });

  final bool inited;
  final bool loading;
  final String? error;
  final String name;
  final double price;
  final String description;

  ProductState copyWith({
    bool? inited,
    bool? loading,
    String? error,
    String? name,
    double? price,
    String? description,
  }) {
    return ProductState(
      inited: inited ?? this.inited,
      loading: loading ?? this.loading,
      error: error,
      name: name ?? this.name,
      price: price ?? this.price,
      description: description ?? this.description,
    );
  }
}

// ===== 控制器定义 ===== //

class ProductController extends FamilyNotifier<ProductState, String> {
  @override
  ProductState build(String productId) {
    // 为每个 productId 创建独立的初始状态
    return const ProductState();
  }

  // 复杂逻辑：初始化加载，确保幂等性
  Future<void> init() async {
    // 防止重复初始化
    if (state.inited) {
      print('已初始化，跳过: $arg');
      return;
    }

    print('开始初始化: $arg');
    state = state.copyWith(loading: true);

    try {
      // 模拟网络请求
      final data = await _loadProduct(arg);

      state = state.copyWith(
        inited: true,
        loading: false,
        name: data['name'],
        price: data['price'],
        description: data['description'],
      );

      print('初始化完成: $arg');
    } catch (e) {
      state = state.copyWith(
        loading: false,
        error: e.toString(),
      );

      print('初始化失败: $arg, $e');
    }
  }

  Future<Map<String, dynamic>> _loadProduct(String productId) async {
    // 模拟API调用延迟
    await Future.delayed(const Duration(seconds: 1));

    // 模拟返回数据
    return {
      'name': '商品-$productId',
      'price': 99.99,
      'description': '这是商品 $productId 的描述',
    };
  }

  // 更新字段
  void updateName(String name) {
    state = state.copyWith(name: name);
  }

  void updatePrice(double price) {
    state = state.copyWith(price: price);
  }

  void updateDescription(String description) {
    state = state.copyWith(description: description);
  }

  // 提交保存
  Future<void> save() async {
    state = state.copyWith(loading: true, error: null);

    try {
      await _saveProduct();

      state = state.copyWith(loading: false);
      print('保存成功: $arg');
    } catch (e) {
      state = state.copyWith(
        loading: false,
        error: e.toString(),
      );

      print('保存失败: $arg, $e');
      rethrow;
    }
  }

  Future<void> _saveProduct() async {
    await Future.delayed(const Duration(seconds: 1));
    print('提交数据: 商品ID=$arg, 名称=${state.name}, 价格=${state.price}');
  }

  // 重置状态
  void reset() {
    state = const ProductState();
  }
}

// ===== Provider 定义 ===== //

final productControllerProvider =
    NotifierProvider.family<ProductController, ProductState, String>(
  ProductController.new,
);
```

#### 2. 实现页面

```dart
class ProductEditPage extends ConsumerStatefulWidget {
  const ProductEditPage({super.key, required this.productId});

  final String productId;

  @override
  ConsumerState<ProductEditPage> createState() => _ProductEditPageState();
}

class _ProductEditPageState extends ConsumerState<ProductEditPage> {
  // 表单控制器
  late final TextEditingController _nameController;
  late final TextEditingController _priceController;
  late final TextEditingController _descController;

  @override
  void initState() {
    super.initState();

    // 初始化控制器
    _nameController = TextEditingController();
    _priceController = TextEditingController();
    _descController = TextEditingController();

    // 复杂逻辑：等首帧绘制完成后初始化数据
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;

      // 复杂逻辑：触发数据加载
      ref.read(productControllerProvider(widget.productId).notifier).init();
    });

    // 复杂逻辑：监听状态变化，同步到表单控制器
    ref.listenManual(productControllerProvider(widget.productId), (prev, next) {
      if (!mounted) return;

      // 数据加载完成后，更新表单
      if (next.inited && !next.loading) {
        _nameController.text = next.name;
        _priceController.text = next.price.toString();
        _descController.text = next.description;
      }

      // 显示错误提示
      if (next.error != null) {
        _showError(next.error!);
      }
    });
  }

  @override
  void dispose() {
    _nameController.dispose();
    _priceController.dispose();
    _descController.dispose();
    super.dispose();
  }

  void _showError(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message)),
    );
  }

  Future<void> _handleSave() async {
    try {
      await ref
          .read(productControllerProvider(widget.productId).notifier)
          .save();

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('保存成功')),
        );
        Navigator.pop(context);
      }
    } catch (e) {
      // 错误已在 controller 中处理
    }
  }

  @override
  Widget build(BuildContext context) {
    final state = ref.watch(productControllerProvider(widget.productId));

    return Scaffold(
      appBar: AppBar(
        title: Text('编辑商品 ${widget.productId}'),
        actions: [
          if (state.loading)
            const Center(
              child: Padding(
                padding: EdgeInsets.symmetric(horizontal: 16.0),
                child: SizedBox(
                  width: 20,
                  height: 20,
                  child: CircularProgressIndicator(strokeWidth: 2),
                ),
              ),
            ),
        ],
      ),
      body: !state.inited
          ? const Center(child: CircularProgressIndicator())
          : SingleChildScrollView(
              padding: const EdgeInsets.all(16.0),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  TextField(
                    controller: _nameController,
                    decoration: const InputDecoration(
                      labelText: '商品名称',
                      border: OutlineInputBorder(),
                    ),
                    onChanged: (value) {
                      ref
                          .read(productControllerProvider(widget.productId).notifier)
                          .updateName(value);
                    },
                  ),
                  const SizedBox(height: 16),
                  TextField(
                    controller: _priceController,
                    decoration: const InputDecoration(
                      labelText: '价格',
                      border: OutlineInputBorder(),
                      prefixText: '¥ ',
                    ),
                    keyboardType: TextInputType.number,
                    onChanged: (value) {
                      final price = double.tryParse(value) ?? 0.0;
                      ref
                          .read(productControllerProvider(widget.productId).notifier)
                          .updatePrice(price);
                    },
                  ),
                  const SizedBox(height: 16),
                  TextField(
                    controller: _descController,
                    decoration: const InputDecoration(
                      labelText: '描述',
                      border: OutlineInputBorder(),
                    ),
                    maxLines: 5,
                    onChanged: (value) {
                      ref
                          .read(productControllerProvider(widget.productId).notifier)
                          .updateDescription(value);
                    ),
                  ),
                  const SizedBox(height: 32),
                  ElevatedButton(
                    onPressed: state.loading ? null : _handleSave,
                    child: Padding(
                      padding: const EdgeInsets.all(12.0),
                      child: Text(
                        state.loading ? '保存中...' : '保存',
                        style: const TextStyle(fontSize: 16),
                      ),
                    ),
                  ),
                ],
              ),
            ),
    );
  }
}
```

