class ProductListPage extends ConsumerWidget {
  const ProductListPage({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final products = ['prod-1', 'prod-2', 'prod-3'];

    return Scaffold(
      appBar: AppBar(title: const Text('商品列表')),
      body: ListView.builder(
        itemCount: products.length,
        itemBuilder: (context, index) {
          final productId = products[index];

          return ListTile(
            title: Text('商品 $productId'),
            onTap: () {
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (context) => ProductEditPage(
                    productId: productId,
                  ),
                ),
              );
            },
          );
        },
      ),
    );
  }
}
```

## 最佳实践总结

### 1. 初始化时机

```dart
// ✅ 推荐：addPostFrameCallback + mounted 检查
@override
void initState() {
  super.initState();
  WidgetsBinding.instance.addPostFrameCallback((_) {
    if (!mounted) return;
    ref.read(provider.notifier).init();
  });
}

// ❌ 避免：直接在 initState
@override
void initState() {
  super.initState();
  ref.read(provider.notifier).init(); // 可能太早
}

// ❌ 避免：在 build 中
@override
Widget build(BuildContext context) {
  ref.read(provider.notifier).init(); // 每次 rebuild 都调用！
  return Container();
}
```

### 2. ref 使用规则

```dart
// watch：监听状态，自动重建
final state = ref.watch(provider);

// read：一次性读取，调用方法
ref.read(provider.notifier).doSomething();

// listen：监听变化，执行副作用
ref.listen(provider, (prev, next) {
  if (next.error != null) {
    showError(next.error!);
  }
});

// listenManual：手动管理监听器
ref.listenManual(provider, (prev, next) {
  // 不会自动取消，需要在 dispose 中处理
});
```

### 3. 幂等性保护

```dart
class MyController extends Notifier<MyState> {
  @override
  MyState build() => const MyState();

  Future<void> init() async {
    // ✅ 防止重复初始化
    if (state.inited) return;

    // ✅ 使用标志位
    if (_isInitializing) return;
    _isInitializing = true;

    try {
      // 执行初始化...
      state = state.copyWith(inited: true);
    } finally {
      _isInitializing = false;
    }
  }

  bool _isInitializing = false;
}
```

### 4. 错误处理

```dart
class MyController extends Notifier<MyState> {
  @override
  MyState build() => const MyState();

  Future<void> loadData() async {
    state = state.copyWith(loading: true, error: null);

    try {
      final data = await api.fetchData();
      state = state.copyWith(
        loading: false,
        data: data,
      );
    } catch (e, stackTrace) {
      // ✅ 记录错误
      print('加载失败: $e');
      print(stackTrace);

      // ✅ 更新状态
      state = state.copyWith(
        loading: false,
        error: e.toString(),
      );

      // ✅ 可选：重新抛出
      rethrow;
    }
  }
}
```

### 5. 资源清理

```dart
class MyPage extends ConsumerStatefulWidget {
  @override
  ConsumerState<MyPage> createState() => _MyPageState();
}

class _MyPageState extends ConsumerState<MyPage> {
  late final TextEditingController _controller;

  @override
  void initState() {
    super.initState();
    _controller = TextEditingController();
  }

  @override
  void dispose() {
    // ✅ 清理控制器
    _controller.dispose();

    // ✅ 可选：清理 Provider（如果使用 autoDispose 可省略）
    // ref.invalidate(myProvider);

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Container();
  }
}
```

## 常见陷阱与解决方案

### 陷阱 1：忘记检查 mounted

```dart
// ❌ 错误
WidgetsBinding.instance.addPostFrameCallback((_) {
  ref.read(provider.notifier).init();
  setState(() {}); // 可能报错！
});

// ✅ 正确
WidgetsBinding.instance.addPostFrameCallback((_) {
  if (!mounted) return; // 必须检查
  ref.read(provider.notifier).init();
});
```

### 陷阱 2：在 build 中调用方法

```dart
// ❌ 错误
@override
Widget build(BuildContext context) {
  ref.read(provider.notifier).init(); // 每次 rebuild 都调用
  return Container();
}

// ✅ 正确
@override
void initState() {
  super.initState();
  WidgetsBinding.instance.addPostFrameCallback((_) {
    if (!mounted) return;
    ref.read(provider.notifier).init();
  });
}
```

### 陷阱 3：循环依赖

```dart
// ❌ 错误
final providerA = Provider((ref) {
  final b = ref.watch(providerB); // 依赖 B
  return A(b);
});

final providerB = Provider((ref) {
  final a = ref.watch(providerA); // 依赖 A，循环！
  return B(a);
});

// ✅ 正确：重新设计依赖关系
final baseProvider = Provider((ref) => Base());

final providerA = Provider((ref) {
  final base = ref.watch(baseProvider);
  return A(base);
});

final providerB = Provider((ref) {
  final base = ref.watch(baseProvider);
  return B(base);
});
```

### 陷阱 4：过度使用 Family

```dart
// ❌ 不推荐：参数是可变对象
final provider = Provider.family<State, List<String>>(...);

// ✅ 推荐：参数是不可变值
final provider = Provider.family<State, String>(...);

// ✅ 推荐：使用 record 或不可变类
final provider = Provider.family<State, ({String keyword, int page})>(...);
```

## 总结

### 核心原则

1. **等首帧完成**：使用 `addPostFrameCallback`
2. **检查 mounted**：避免访问已销毁的组件
3. **幂等性保护**：防止重复初始化
4. **错误处理**：完善的错误捕获和提示
5. **资源清理**：及时释放资源

### 代码清单

