### 4. 响应式尺寸

```typescript
@Entry
@Component
struct ResponsiveIcon {
  // 根据设备宽度调整图标尺寸
  @State iconSize: number = 24;

  aboutToAppear(): void {
    // 获取屏幕宽度
    const screenWidth = 360; // 实际项目中从设备信息获取

    if (screenWidth < 360) {
      this.iconSize = 20;
    } else if (screenWidth < 480) {
      this.iconSize = 24;
    } else {
      this.iconSize = 32;
    }
  }

  build() {
    Image($r('app.media.icon_home'))
      .width(this.iconSize)
      .height(this.iconSize)
      .renderMode(ImageRenderMode.Template)
      .fillColor('#4A90E2')
  }
}
```

### 5. 动态加载与缓存

```typescript
@Entry
@Component
struct DynamicIconLoading {
  @State iconList: Resource[] = [];
  @State isLoading: boolean = true;

  async aboutToAppear() {
    // 模拟异步加载图标配置
    await this.loadIcons();
  }

  async loadIcons(): Promise<void> {
    this.isLoading = true;

    // 实际项目中从服务器或配置文件加载
    this.iconList = [
      $r('app.media.icon_home'),
      $r('app.media.icon_message'),
      $r('app.media.icon_settings')
    ];

    this.isLoading = false;
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('加载中...')
      } else {
        ForEach(this.iconList, (icon: Resource) => {
          Image(icon)
            .width(32)
            .height(32)
            .margin(10)
        })
      }
    }
  }
}
```

