## 五、最佳实践指南

### 5.1 何时使用 Getter 派生

```typescript
/**
 * ✅ 应该使用 Getter 的场景
 */

// 场景 1：纯数据同步（最常见）
const config = reactive({
  get userName() {
    return user.value.name;
  },
  get userAge() {
    return user.value.age;
  },
});

// 场景 2：简单计算
const config = reactive({
  get fullName() {
    return `${firstName.value} ${lastName.value}`;
  },
  get isAdult() {
    return age.value >= 18;
  },
});

// 场景 3：数据转换
const config = reactive({
  get priceInYuan() {
    return priceInCents.value / 100;
  },
  get formattedDate() {
    return formatDate(rawDate.value);
  },
});

// 场景 4：条件读取
const config = reactive({
  get effectivePrice() {
    return hasDiscount.value ? discountPrice.value : originalPrice.value;
  },
});

// 场景 5：安全访问
const config = reactive({
  get userName() {
    return user.value?.name ?? "Guest";
  },
});
```

### 5.2 何时必须使用 Watch

```typescript
/**
 * ✅ 必须使用 Watch 的场景
 */

// 场景 1：副作用操作（API 调用、DOM 操作）
watch(userId, async (id) => {
  loading.value = true;
  try {
    const data = await fetchUserData(id); // 副作用
    userData.value = data;
  } finally {
    loading.value = false;
  }
});

// 场景 2：需要历史值对比
watch(count, (newVal, oldVal) => {
  const delta = newVal - oldVal;
  console.log(`Changed by: ${delta}`);

  if (newVal > oldVal) {
    showNotification("Count increased!");
  }
});

// 场景 3：需要清理函数
watch(activeTab, (newTab, oldTab, onCleanup) => {
  const timer = setInterval(() => {
    updateTabData(newTab);
  }, 1000);

  // 清理上一个定时器
  onCleanup(() => {
    clearInterval(timer);
  });
});

// 场景 4：防抖/节流
watch(
  searchQuery,
  debounce((query) => {
    performSearch(query);
  }, 300)
);

// 场景 5：深度监听复杂对象（谨慎使用）
watch(
  () => formData,
  (newData) => {
    validateForm(newData);
    saveToLocalStorage(newData);
  },
  { deep: true }
);
```

### 5.3 Getter vs Computed 的选择

```typescript
/**
 * Getter vs Computed 的选择指南
 */

// ✅ 使用 Getter：作为对象的属性
const config = reactive({
  get fullName() {
    return `${firstName.value} ${lastName.value}`;
  },
  get isValid() {
    return age.value >= 18;
  },
});

// 使用场景：
// - 需要保持对象引用稳定
// - 作为配置对象的一部分
// - 需要将多个派生值组合在一起

// ✅ 使用 Computed：独立的计算属性
const fullName = computed(() => `${firstName.value} ${lastName.value}`);
const isValid = computed(() => age.value >= 18);

// 使用场景：
// - 独立的派生值
// - 需要单独导出
// - 计算逻辑复杂，需要缓存

// 💡 经验法则：
// - 如果值是某个对象的"属性"，用 Getter
// - 如果值是独立的"变量"，用 Computed
```

### 5.4 对象引用稳定性保证

```typescript
/**
 * 保证对象引用稳定的技巧
 */

// ✅ 方案 1：Reactive + Getter（推荐）
const config = reactive({
  get value() { return source.value }
})

// config 的引用永远不变
const ref1 = config
source.value = 'new value'
const ref2 = config
console.log(ref1 === ref2)  // true ✅

// ❌ 方案 2：Computed 返回对象（不推荐）
const config = computed(() => ({
  value: source.value
}))

// config.value 的引用每次都变
const ref1 = config.value
source.value = 'new value'
const ref2 = config.value
console.log(ref1 === ref2)  // false ❌

// 💡 原因：
// - reactive 创建的代理对象引用不变
// - computed 每次返回新对象
// - getter 是 reactive 对象的一部分

// 实际应用
const Parent = {
  setup() {
    // ✅ config 可以安全传递给子组件
    const { config } = useConfig(...)

    return { config }
  }
}

const Child = {
  props: ['config'],
  setup(props) {
    // props.config 的引用始终稳定
    // 但内部值会响应式更新
    watch(
      () => props.config.lots,
      (lots) => console.log(lots)
    )
  }
}
```

### 5.5 性能优化技巧

```typescript
/**
 * 性能优化最佳实践
 */

// ✅ 技巧 1：避免不必要的深度监听
// ❌ 不好
watch(
  () => config,
  (newConfig) => {
    /* ... */
  },
  { deep: true } // 性能开销大
);

// ✅ 更好：只监听需要的字段
watch(
  () => config.specificField,
  (newValue) => {
    /* ... */
  }
);

// ✅ 技巧 2：使用 Getter 代替 Computed 缓存
// 如果值的计算非常简单，getter 比 computed 更轻量
const config = reactive({
  // ✅ 简单计算，用 getter
  get doubled() {
    return value.value * 2;
  },

  // ✅ 复杂计算，用 computed
  get complexValue() {
    return computedComplexValue.value;
  },
});

const computedComplexValue = computed(() => {
  // 复杂计算逻辑
  return heavyComputation(data.value);
});

// ✅ 技巧 3：合并多个 watch
// ❌ 不好
watch(field1, () => {
  /* ... */
});
watch(field2, () => {
  /* ... */
});
watch(field3, () => {
  /* ... */
});

// ✅ 更好
watch([field1, field2, field3], () => {
  /* ... */
});

// ✅ 技巧 4：使用 watchEffect 自动追踪
// 当需要监听多个源时
watchEffect(() => {
  // 自动追踪所有读取的响应式数据
  console.log(field1.value, field2.value, field3.value);
});
```

