#### 3.1.3 子组件设计原则

```typescript
/**
 * 优秀子组件的特征
 */

// 1. 清晰的 Props 接口
interface GoodComponentProps {
  // ✅ 必需的 props 用 required
  data: DataType

  // ✅ 可选的 props 提供默认值
  theme?: 'light' | 'dark' // default: 'light'

  // ✅ Props 类型明确
  count: number
  items: Array<Item>

  // ❌ 避免传递整个对象
  // config: Record<string, any>
}

// 2. 明确的 Emits 定义
const emit = defineEmits<{
  // ✅ 事件名语义化
  'update:value': [value: string]
  'submit': [data: FormData]
  'error': [error: Error]

  // ❌ 避免模糊的事件名
  // 'change': []
  // 'action': []
}>()

// 3. 合理的 Expose
defineExpose({
  // ✅ 只暴露必要的方法
  focus: () => inputRef.value?.focus()
  reset: () => form.value = initialValue

  // ❌ 不要暴露内部状态
  // _internalState: state
})

// 4. 插槽的使用
<template>
  <!-- ✅ 提供命名插槽增加灵活性 -->
  <div class="card">
    <slot name="header" />
    <slot /> <!-- 默认插槽 -->
    <slot name="footer" />
  </div>

  <!-- ✅ 作用域插槽传递数据 -->
  <slot name="item" :item="item" :index="index" />
</template>
