### 技巧 2：结合 LazyScope 实现条件性渲染

```typescript
import { h, defineComponent } from "vue";
import LazyScope from "@/components/LazyScope";

export default defineComponent({
  setup() {
    const hasData = ref(false);

    return () =>
      h(
        LazyScope,
        {
          when: hasData.value,
          factory: () => ({
            // 创建昂贵的上下文
