### 技巧 3：TypeScript 类型增强

```typescript
import { h, defineComponent, VNode, PropType } from "vue";

interface ButtonProps {
  type: "primary" | "default" | "danger";
  size: "small" | "medium" | "large";
  disabled?: boolean;
  onClick?: () => void;
}

export default defineComponent({
  name: "TypedButton",
  props: {
    type: {
      type: String as PropType<ButtonProps["type"]>,
      default: "default",
    },
    size: {
      type: String as PropType<ButtonProps["size"]>,
      default: "medium",
    },
    disabled: Boolean,
  },
  emits: {
    click: () => true,
  },
  setup(props, { emit, slots }) {
    const handleClick = () => {
      if (!props.disabled) {
        emit("click");
      }
    };

    return (): VNode =>
      h(
        "button",
        {
          class: ["btn", `btn-${props.type}`, `btn-${props.size}`],
          disabled: props.disabled,
          onClick: handleClick,
        },
        slots.default?.()
      );
  },
});
```

### 技巧 4：Teleport 与渲染函数

```typescript
import { h, Teleport, ref } from "vue";

export default {
  setup() {
    const show = ref(false);

    return () =>
      h(
        Teleport,
        {
          to: "body", // 传送到 body
        },
        show.value
          ? h("div", { class: "modal" }, [
              h("div", { class: "modal-content" }, "Modal Content"),
              h(
                "button",
                {
                  onClick: () => (show.value = false),
                },
                "Close"
              ),
            ])
          : null
      );
  },
};
```

### 技巧 5：性能优化（v-memo 模拟）

```typescript
import { h, ref, shallowRef } from "vue";

export default {
  setup() {
    const list = ref([
      /* 大量数据 */
    ]);
    const cachedVNodes = shallowRef<VNode[]>([]);

    return () => {
      // 复杂逻辑：仅在数据变化时重新生成 VNode
      if (cachedVNodes.value.length === 0) {
        cachedVNodes.value = list.value.map((item) =>
          h("div", { key: item.id }, item.name)
        );
      }

      return h("div", cachedVNodes.value);
    };
  },
};
```

