## 2）中间省略指令/Hook（Vue / React 皆可迁移）

```ts
// 上一行注释：在挂载和尺寸变化时根据容器宽度替换文本为中间省略
const useMiddleEllipsis = (el: HTMLElement, text: string) => {
  const ro = new ResizeObserver(() => {
    el.textContent = middleEllipsisByWidth(text, el);
  });
  ro.observe(el);
  // 上一行注释：卸载时清理监听
  return () => ro.disconnect();
};
```

