else if (['image', 'file'].includes(field.controlType ?? '')) {
  rules.push(
    { validator: uploadChangeRule(field.label), trigger: ['change'] },
    { validator: uploadSubmitRule(field.label, field.required !== false), trigger: ['submit'] },
