## 七、创建语言切换组件

```vue
<!-- src/components/LanguageSwitcher.vue -->
<template>
  <a-select
    v-model:value="currentLocale"
    style="width: 160px"
    @change="handleLocaleChange"
  >
    <a-select-option
      v-for="locale in supportedLocales"
      :key="locale"
      :value="locale"
    >
      {{ getLocaleLabel(locale) }}
    </a-select-option>
  </a-select>
</template>

<script setup lang="ts">
import { ref, computed } from "vue";
import { useI18n } from "vue-i18n";
import { SUPPORT_LOCALES } from "@/locales";
import { setLocale } from "@/utils/i18nHelper";

const { locale, messages } = useI18n();

// 当前语言
const currentLocale = computed({
  get: () => locale.value,
  set: (val) => {
    locale.value = val;
  },
});

// 支持的语言列表
const supportedLocales = ref(SUPPORT_LOCALES);

// 复杂逻辑：从语言文件中读取语言标签
const getLocaleLabel = (locale: string): string => {
  const langData = messages.value[locale] as any;
  return langData?.lang?.label || locale;
};

// 复杂逻辑：切换语言并同步所有配置
const handleLocaleChange = (newLocale: string) => {
  setLocale(newLocale);

  // 可选：刷新页面以确保所有内容更新
  // window.location.reload()
};
</script>
```

