  operator: "AND" | "OR";
  conditions: Condition[];
  [k: string]: any;
}

export interface SecurityBeginData {
  begin_time: string;
  expire_time: string;
  passage_key: string;
  security_code: string;
  status: "0" | "1";
  steps: Step[];
  use_cnt: string;
  [k: string]: any;
}

export interface SecurityBeginRes {
  code: number;
  message: string;
  data: SecurityBeginData;
}

export type VerifyProof = { ok: boolean; proof?: string; detail?: any };

// 上一行：统一的验证器接口，便于动态加载与替换
export interface Verifier {
  // 上一行：执行该要素的完整流程（含弹窗/输入/调用后端），返回是否成功
  start(ctx: {
    condition: Condition;
    passageKey: string;
    securityCode: string;
  }): Promise<VerifyProof>;
