    // 复杂逻辑：append 表示仅页码变化（追加）；否则为条件变化（替换）
    const append = newKey === oldKey && newPage !== oldPage;

    // 复杂逻辑：注册失效回调；期间若有新一轮触发，则本次响应丢弃
    let cancelled = false;
    onInvalidate(() => {
      cancelled = true;
    });

    // 复杂逻辑：条件变化前清空现有数据和 hasMore，避免旧状态干扰
