  let s = raw.normalize("NFKC");
  s = s
    .replace(/[’ʻˈʹ`´]/g, "'")
    .replace(/\s+/g, " ")
    .replace(/[ .\-']{2,}/g, (m) => m[0])
    .replace(/^[ .\-']+|[ .\-']+$/g, "")
    .replace(/\p{C}/gu, "");
  return s;
}
```

