  id: number;
  name: string;
  age: number;
};

let person: PersonType = { id: 1, name: "张三", age: 25 };

// for-in 遍历 (HBuilderX 3.9+)
for (let key in person) {
  console.log(key); // 输出 "id", "name", "age"
}

// 下标访问 (HBuilderX 3.9+)
