#### 1. 堆栈

堆栈就像一堆盘子。您添加到顶部（推送），并从顶部删除（弹出）。

运营：

-`push(x)`→ 将项目添加到顶部
-`pop()`→ 删除顶部项目
-`peek()`→ 查看顶部的项目而不将其移除

#### 使用链表实现堆栈

每个堆栈节点保存数据和指向下一个节点的指针。

```
#include <stdio.h>
#include <stdlib.h>
typedef struct Node {
    int value;
    struct Node *next;
} Node;
typedef struct {
    Node *top;
} Stack;
Stack* create_stack(void) {
    Stack *s = malloc(sizeof(Stack));
    s->top = NULL;
    return s;
}
void push(Stack *s, int value) {
    Node *n = malloc(sizeof(Node));
    n->value = value;
    n->next = s->top;
    s->top = n;
}
int pop(Stack *s) {
    if (!s->top) {
        printf("Stack underflow!\n");
        return -1;
    }
    Node *temp = s->top;
    int val = temp->value;
    s->top = temp->next;
    free(temp);
    return val;
}
int peek(const Stack *s) {
    return s->top ? s->top->value : -1;
}
void free_stack(Stack *s) {
    while (s->top) pop(s);
    free(s);
}
int main(void) {
    Stack *s = create_stack();
    push(s, 10);
    push(s, 20);
    push(s, 30);
    printf("Top: %d\n", peek(s));
    printf("Popped: %d\n", pop(s));
    printf("Popped: %d\n", pop(s));
    printf("Top now: %d\n", peek(s));
    free_stack(s);
    return 0;
}
```

输出：

```
Top: 30
Popped: 30
Popped: 20
Top now: 10
```

#### 为什么使用堆栈？

堆栈用于：

- 函数调用（调用堆栈）
- 撤消/重做系统
- 解析表达式（例如，评估`(2 + 3) * 4`)
- 图中的深度优先搜索（DFS）

#### 2. 队列

队列就像商店里的队伍。您添加到后面（入队），并从前面删除（出队）。

运营：

-`enqueue(x)`→ 添加到末尾
-`dequeue()`→ 从前面拆下

#### 使用链表实现队列

```
#include <stdio.h>
#include <stdlib.h>
typedef struct Node {
    int value;
    struct Node *next;
} Node;
typedef struct {
    Node *front;
    Node *rear;
} Queue;
Queue* create_queue(void) {
    Queue *q = malloc(sizeof(Queue));
    q->front = q->rear = NULL;
    return q;
}
void enqueue(Queue *q, int value) {
    Node *n = malloc(sizeof(Node));
    n->value = value;
    n->next = NULL;
    if (q->rear == NULL) {
        q->front = q->rear = n;
        return;
    }
    q->rear->next = n;
    q->rear = n;
}
int dequeue(Queue *q) {
    if (q->front == NULL) {
        printf("Queue underflow!\n");
        return -1;
    }
    Node *temp = q->front;
    int val = temp->value;
    q->front = temp->next;
    if (q->front == NULL)
        q->rear = NULL;
    free(temp);
    return val;
}
void print_queue(const Queue *q) {
    for (Node *p = q->front; p != NULL; p = p->next)
        printf("%d ", p->value);
    printf("\n");
}
void free_queue(Queue *q) {
    while (q->front) dequeue(q);
    free(q);
}
int main(void) {
    Queue *q = create_queue();
    enqueue(q, 1);
    enqueue(q, 2);
    enqueue(q, 3);
    printf("Queue: ");
    print_queue(q);
    printf("Dequeued: %d\n", dequeue(q));
    printf("Dequeued: %d\n", dequeue(q));
    printf("Remaining: ");
    print_queue(q);
    free_queue(q);
    return 0;
}
```

输出：

```
Queue: 1 2 3 
Dequeued: 1
Dequeued: 2
Remaining: 3
```

