// 创建Dao接口实现类使用了代理模式
// 优势：不修改源码的基础上对已有方法增强

IUserDao userDao = session.getMapper(IUserDao.class);
//6.
使用代理对象执行查询所有方法

List\<User\> users = userDao.findAll();
for(User user : users) \{
System.out.println(user);
\}
//7.
释放资源

session.close();
in.close();
\}
\}
