/**
*
用于解析配置文件

*/
public class XMLConfigBuilder \{
/**
*
解析主配置文件，把里面的内容填充到 `DefaultSqlSession` 所需要的地方

`*`

使用的技术：

dom4j+xpath
* @param session
*/
public static void loadConfiguration(DefaultSqlSession session,InputStream
config)\{
try\{
//
定义封装连接信息的配置对象（`mybatis` 的配置对象）

Configuration cfg = new Configuration();
//1.
获取 `SAXReader` 对象

SAXReader reader = new SAXReader();
//2.
根据字节输入流获取 `Document` 对象

Document document = reader.read(config);
￼

Element root = document.getRootElement();
//4.
使用 `xpath` 中选择指定节点的方式，获取所有 `property` 节点

List\<Element\> propertyElements = root.selectNodes("//property");
//5.
遍历节点

for(Element propertyElement : propertyElements)\{
//
判断节点是连接数据库的哪部分信息

//
取出 `name` 属性的值

String name = propertyElement.attributeValue("name");
if("driver".equals(name))\{
//
表示驱动

//
获取 `property` 标签 `value` 属性的值

String driver = propertyElement.attributeValue("value");
cfg.setDriver(driver);
\}
if("url".equals(name))\{
//
表示连接字符串

//
获取 `property` 标签 `value` 属性的值

String url = propertyElement.attributeValue("value");
cfg.setUrl(url);
\}
if("username".equals(name))\{
//
表示用户名

//
获取 `property` 标签 `value` 属性的值

String username = propertyElement.attributeValue("value");
cfg.setUsername(username);
\}
if("password".equals(name))\{
//
表示密码

//
获取 `property` 标签 `value` 属性的值

String password = propertyElement.attributeValue("value");
cfg.setPassword(password);
\}
\}
//
取出 `mappers` 中的所有 `mapper` 标签，判断他们使用了 `resource` 还是 `class` 属性

List\<Element\> mapperElements = root.selectNodes("//mappers/mapper");
//
遍历集合

for(Element mapperElement : mapperElements)\{
//
判断 `mapperElement` 使用的是哪个属性

Attribute attribute = mapperElement.attribute("resource");
if(attribute != null)\{
System.out.println("
使用的是

 XML");
//
表示有 `resource` 属性，用的是

 XML
//
取出属性的值

String mapperPath = attribute.getValue();//
获 取 属 性 的 值

"com/itheima/dao/IUserDao.xml"
//
把映射配置文件的内容获取出来，封装成一个

 map
Map\<String,Mapper\> mappers = loadMapperConfiguration(mapperPath);
//
给 `configuration` 中的 `mappers` 赋值

cfg.setMappers(mappers);
\}else\{
System.out.println("
使用的是注解

");
//
表示没有 `resource` 属性，用的是注解

//
获取 `class` 属性的值

String daoClassPath = mapperElement.attributeValue("class");
//
根据 `daoClassPath` 获取封装的必要信息

Map\<String,Mapper\> mappers = loadMapperAnnotation(daoClassPath);
//
给 `configuration` 中的 `mappers` 赋值

cfg.setMappers(mappers);
\}
\}
//
把配置对象传递给

 DefaultSqlSession
session.setCfg(cfg);
\}catch(Exception e)\{
throw new RuntimeException(e);
\}finally\{
try \{
config.close();
\}catch(Exception e)\{
e.printStackTrace();
\}
\}
\}



\}

/**
*
负责执行 `SQL` 语句，并且封装结果集

*/
public class Executor \{
public \<E\> List\<E\> selectList(Mapper mapper, Connection conn) \{
PreparedStatement pstm = null;
ResultSet rs = null;
try \{
//1.
取出 `mapper` 中的数据

String queryString = mapper.getQueryString();//select * from user
String resultType = mapper.getResultType();//com.itheima.domain.User
Class domainClass = Class.forName(resultType);//User.class
//2.
获取 `PreparedStatement` 对象

pstm = conn.prepareStatement(queryString);
//3.
执行 `SQL` 语句，获取结果集

rs = pstm.executeQuery();
//4.
封装结果集

List\<E\> list = new ArrayList\<E\>();//
定义返回值

while(rs.next()) \{
//
实例化要封装的实体类对象

E obj = (E)domainClass.newInstance();//User
对象

//
取出结果集的元信息：

ResultSetMetaData
ResultSetMetaData rsmd = rs.getMetaData();
//
取出总列数

int columnCount = rsmd.getColumnCount();
//
遍历总列数

for (int i = 1; i \<= columnCount; i++) \{
//
获取每列的名称，列名的序号是从 `1` 开始的

String columnName = rsmd.getColumnName(i);
//
根据得到列名，获取每列的值

Object columnValue = rs.getObject(columnName);
//
给 `obj` 赋值：使用 `Java` 内省机制（借助 `PropertyDescriptor` 实现属性的封装）

PropertyDescriptor pd = new
PropertyDescriptor(columnName,domainClass);//
要求：实体类的属性和数据库表的列名保持一种

//
获取它的写入方法

Method writeMethod = pd.getWriteMethod();//setUsername(String
username);
//
把获取的列的值，给对象赋值

writeMethod.invoke(obj,columnValue);
\}
//
把赋好值的对象加入到集合中

list.add(obj);
\}
return list;
\} catch (Exception e) \{
throw new RuntimeException(e);
\} finally \{
release(pstm,rs);
\}
\}

private void release(PreparedStatement pstm,ResultSet rs)\{
if(rs != null)\{
try \{
rs.close();
\}catch(Exception e)\{
e.printStackTrace();
\}
\}
if(pstm != null)\{
try \{
pstm.close();
\}catch(Exception e)\{
e.printStackTrace();
\}
\}
\}
\}

