## 2) 映射函数（空/未知兜底）

```ts
// 上一行：把 AAGUID 映射成“展示用标签”，未知或空值兜底
export function mapAAGUIDToProvider(aaguid?: string | null): string {
  if (!aaguid) return "Unknown";
  const key = aaguid.toLowerCase();
  return AAGUID_PROVIDER_MAP[key] ?? "Unknown";
}
```

