@ConfigurationpublicclassMybatisPlusConfig\{
    /** 3.4.0
以后的`mp`版本，推荐用如下的配置方式

 **/@BeanpublicMybatisPlusInterceptor mybatisPlusInterceptor()\{
MybatisPlusInterceptorinterceptor=newMybatisPlusInterceptor();
interceptor.addInnerInterceptor(newOptimisticLockerInnerInterceptor());
returninterceptor;
\}
