interceptor.addInnerInterceptor(newTenantLineInnerInterceptor(newTenantLineHandler() \{
@OverridepublicExpression getTenantId()\{
//
返回租户`id`的值`,` 这里固定写死为`1//` 一般是从当前上下文中取出一个 租户

idreturnnewLongValue(1);
\}
